/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountParallaxMountains, type ParallaxMountainsOptions } from "../../components/parallax-mountains/ParallaxMountainsEngine.js";
import type { MotionController } from "../../components/parallax-mountains/motion-runtime";

export function ParallaxMountains({ options, className }: { options?: ParallaxMountainsOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountParallaxMountains(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="parallax-mountains" />;
}

